const ADMIN_JS = "\n(()=>{'use strict';const $=id=>document.getElementById(id);let products=[],articles=[];const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function call(path,method='GET',body){const r=await fetch(path,{method,headers:{'Content-Type':'application/json'},credentials:'same-origin',body:body?JSON.stringify(body):undefined,cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'Erreur serveur');return j}\nfunction specsToText(s){return Object.entries(s||{}).map(([k,v])=>k+': '+v).join('\\n')}\nfunction textToSpecs(s){const o={};for(const l of s.split('\\n')){const i=l.indexOf(':');if(i>0){const k=l.slice(0,i).trim(),v=l.slice(i+1).trim();if(k&&v)o[k]=v}}return o}\nfunction render(){const p=$('admin-products');p.innerHTML='<table class=\"v2-table\"><thead><tr><th>Produit</th><th>Catégorie</th><th>État</th><th>Action</th></tr></thead><tbody>'+products.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.category)+'</td><td>'+(x.visible?'Publié':'Brouillon')+'</td><td><button class=\"v2-button alt\" data-edit-product=\"'+esc(x.id)+'\">Modifier</button> <button class=\"v2-button alt\" data-del-product=\"'+esc(x.id)+'\">Supprimer</button></td></tr>').join('')+'</tbody></table>'; $('admin-articles').innerHTML='<table class=\"v2-table\"><tbody>'+articles.map(a=>'<tr><td>'+esc(a.title)+'</td><td>'+(a.published?'Publié':'Brouillon')+'</td><td><button class=\"v2-button alt\" data-edit-article=\"'+esc(a.id)+'\">Modifier</button> <button class=\"v2-button alt\" data-del-article=\"'+esc(a.id)+'\">Supprimer</button></td></tr>').join('')+'</tbody></table>'}\nasync function load(){try{const j=await call('/api/admin/data');products=j.products;articles=j.articles;$('login-panel').hidden=true;$('admin-panel').hidden=false;$('stats').textContent='Visites avec consentement : '+j.analytics.pageviews+' · clics Amazon : '+j.analytics.clicks+' · répartition : '+JSON.stringify(j.analytics.byProduct);render()}catch{$('login-panel').hidden=false;$('admin-panel').hidden=true}}\n$('login-form').addEventListener('submit',async e=>{e.preventDefault();try{await call('/api/admin/login','POST',{password:$('password').value});$('password').value='';$('login-status').textContent='Connexion réussie';await load()}catch(err){$('login-status').textContent=err.message}});\n$('logout').addEventListener('click',async()=>{await call('/api/admin/logout','POST',{}).catch(()=>{});await load()});\nfunction clearProduct(){$('product-form').reset();$('product-form').elements.id.value='';$('product-form').elements.visible.checked=true}$('product-clear').addEventListener('click',clearProduct);\n$('product-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const obj={};for(const k of ['id','name','category','url','image','description','review'])obj[k]=f.elements[k].value.trim();obj.specs=textToSpecs(f.elements.specs.value);obj.visible=f.elements.visible.checked;try{await call('/api/admin/product','POST',obj);$('product-status').textContent='Produit sauvegardé';clearProduct();await load()}catch(err){$('product-status').textContent=err.message}});\nfunction clearArticle(){$('article-form').reset();$('article-form').elements.id.value='';$('article-form').elements.published.checked=true}$('article-clear').addEventListener('click',clearArticle);\n$('article-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const obj={};for(const k of ['id','title','summary','body'])obj[k]=f.elements[k].value.trim();obj.published=f.elements.published.checked;try{await call('/api/admin/article','POST',obj);$('article-status').textContent='Article sauvegardé';clearArticle();await load()}catch(err){$('article-status').textContent=err.message}});\ndocument.addEventListener('click',async e=>{const p=e.target.closest('[data-edit-product]');if(p){const x=products.find(z=>z.id===p.dataset.editProduct),f=$('product-form');if(!x)return;for(const k of ['id','name','category','url','image','description','review'])f.elements[k].value=x[k]||'';f.elements.specs.value=specsToText(x.specs);f.elements.visible.checked=!!x.visible;f.scrollIntoView({behavior:'smooth'})}const a=e.target.closest('[data-edit-article]');if(a){const x=articles.find(z=>z.id===a.dataset.editArticle),f=$('article-form');if(!x)return;for(const k of ['id','title','summary','body'])f.elements[k].value=x[k]||'';f.elements.published.checked=!!x.published;f.scrollIntoView({behavior:'smooth'})}\nconst dp=e.target.closest('[data-del-product]');if(dp&&confirm('Supprimer ce produit ?')){try{await call('/api/admin/product/'+encodeURIComponent(dp.dataset.delProduct),'DELETE',{});await load()}catch(err){alert(err.message)}}const da=e.target.closest('[data-del-article]');if(da&&confirm('Supprimer cet article ?')){try{await call('/api/admin/article/'+encodeURIComponent(da.dataset.delArticle),'DELETE',{});await load()}catch(err){alert(err.message)}}});\nload();\n})();";

import {Database} from "bun:sqlite";
const db=new Database("/data/pico-web.sqlite",{create:true});db.exec("PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,url TEXT NOT NULL,image TEXT,description TEXT,specs TEXT,review TEXT,visible INTEGER NOT NULL DEFAULT 1); CREATE TABLE IF NOT EXISTS articles(id TEXT PRIMARY KEY,title TEXT NOT NULL,summary TEXT,body TEXT NOT NULL,published INTEGER NOT NULL DEFAULT 1); CREATE TABLE IF NOT EXISTS metrics(k TEXT PRIMARY KEY,n INTEGER NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS clicks(id TEXT PRIMARY KEY,n INTEGER NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS login_attempts(k TEXT PRIMARY KEY,n INTEGER NOT NULL,at INTEGER NOT NULL);");

db.exec("CREATE TABLE IF NOT EXISTS cms_state(k TEXT PRIMARY KEY,json TEXT NOT NULL,updated INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS cms_history(id INTEGER PRIMARY KEY AUTOINCREMENT,json TEXT NOT NULL,created INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS cms_media(id TEXT PRIMARY KEY,name TEXT NOT NULL,mime TEXT NOT NULL,bytes BLOB NOT NULL,size INTEGER NOT NULL,created INTEGER NOT NULL);");
const CMS_DEFAULT={"siteName":"PICO WEB","siteDescription":"Produits et services web","announcement":"Bienvenue sur PICO WEB","colorPrimary":"#163a29","colorAccent":"#2d9271","colorSoft":"#e4f9eb","colorBackground":"#f9fbf9","heroHighlight":"fait la différence.","heroPrimaryLabel":"Découvrir les produits ↗","heroPrimaryLink":"#deals","heroSecondaryLabel":"Nos services","heroSecondaryLink":"#services","heroImage":"","brandLogo":"","menu":[{"label":"Accueil","url":"#hero"},{"label":"Produits","url":"#deals"},{"label":"Comparer","url":"#compare"},{"label":"Services","url":"#services"},{"label":"Blog","url":"#guides"}],"sections":[{"id":"hero","label":"Accueil","eyebrow":"PICO / DIGITAL STUDIO","title":"Le web qui fait la différence.","description":"","visible":true},{"id":"boutique","label":"Sélection Amazon","eyebrow":"PICO / AMAZON SELECTION","title":"Une sélection qui compte.","description":"","visible":true},{"id":"services","label":"Services","eyebrow":"PICO / STUDIO DIGITAL","title":"Des idées aux vrais projets.","description":"","visible":true},{"id":"promo","label":"Bannière","eyebrow":"PICO WEB / NEXT STEP","title":"Vous avez une idée ?","description":"","visible":true},{"id":"questions","label":"FAQ","eyebrow":"PICO / FAQ","title":"Les réponses utiles.","description":"","visible":true},{"id":"deals","label":"PICO DEALS","eyebrow":"PICO / DEALS","title":"Nos sélections Amazon.","description":"","visible":true},{"id":"compare","label":"PICO COMPARE","eyebrow":"PICO / COMPARE","title":"Comparez avec photos.","description":"","visible":true},{"id":"reviews","label":"Reviews","eyebrow":"PICO / REVIEWS","title":"Fiches produits objectives.","description":"","visible":true},{"id":"guides","label":"Blog","eyebrow":"PICO / BLOG","title":"Guides d'achat & conseils.","description":"","visible":true},{"id":"store","label":"Store","eyebrow":"PICO / STORE","title":"Templates & services digitaux.","description":"","visible":true},{"id":"favorites","label":"Favoris","eyebrow":"PICO / FAVORITES","title":"Vos favoris ♡","description":"","visible":true},{"id":"privacy","label":"Confidentialité","eyebrow":"VOTRE VIE PRIVÉE","title":"Votre confidentialité compte.","description":"","visible":true}],"faq":[],"footerTitle":"PICO WEB","footerDescription":"Gaming et création web","footerCopyright":"© PICO WEB","customBlocks":[]};
const initCms=db.prepare("INSERT OR IGNORE INTO cms_state(k,json,updated) VALUES(?,?,?)");
initCms.run("draft",JSON.stringify(CMS_DEFAULT),Date.now());initCms.run("published",JSON.stringify(CMS_DEFAULT),Date.now());
const getCms=k=>{try{return JSON.parse(db.query("SELECT json FROM cms_state WHERE k=?").get(k)?.json||"{}")}catch{return CMS_DEFAULT}};
function cmsClean(x){
if(!x||typeof x!=="object"||Array.isArray(x))throw Error("Invalid site data");
const str=(v,n=900)=>String(v??"").trim().slice(0,n);
const safeUrl=v=>{const s=str(v,1500);if(!s)return "";if(/^#[a-zA-Z0-9_-]+$/.test(s))return s;if(s.startsWith("/media/")&&/^[a-f0-9-]{10,50}$/.test(s.slice(7)))return s;try{const u=new URL(s);return u.protocol==="https:"&&!u.username&&!u.password?s:""}catch{return ""}};
const image=v=>{const s=safeUrl(v);return s.startsWith("https://")||s.startsWith("/media/")?s:""};
const color=(v,f)=>/^#[a-fA-F0-9]{6}$/.test(String(v))?v:f;
const out=structuredClone(CMS_DEFAULT);
for(const k of ["siteName","siteDescription","announcement","heroHighlight","heroPrimaryLabel","heroSecondaryLabel","footerTitle","footerDescription","footerCopyright"])out[k]=str(x[k]??out[k],k==="footerDescription"?1500:400);
for(const k of ["colorPrimary","colorAccent","colorSoft","colorBackground"])out[k]=color(x[k],out[k]);
out.heroImage=image(x.heroImage);out.brandLogo=image(x.brandLogo);
out.heroPrimaryLink=safeUrl(x.heroPrimaryLink)||"#deals";out.heroSecondaryLink=safeUrl(x.heroSecondaryLink)||"#services";
if(Array.isArray(x.menu))out.menu=x.menu.slice(0,12).map(m=>({label:str(m.label,55),url:safeUrl(m.url)})).filter(m=>m.label&&m.url);
if(Array.isArray(x.sections)){const allowed=new Set(CMS_DEFAULT.sections.map(s=>s.id));const seen=new Set();out.sections=x.sections.filter(s=>allowed.has(s.id)&&!seen.has(s.id)&&seen.add(s.id)).map(s=>({id:s.id,label:str(s.label,65),eyebrow:str(s.eyebrow,100),title:str(s.title,175),description:str(s.description,1300),image:image(s.image),visible:s.visible!==false}));for(const s of CMS_DEFAULT.sections)if(!seen.has(s.id))out.sections.push(s)}
if(Array.isArray(x.faq))out.faq=x.faq.slice(0,20).map(f=>({question:str(f.question,180),answer:str(f.answer,1400)})).filter(f=>f.question&&f.answer);
if(Array.isArray(x.customBlocks))out.customBlocks=x.customBlocks.slice(0,20).map((b,i)=>({id:/^[a-z0-9-]{4,48}$/.test(String(b.id))?b.id:"custom-"+i+"-"+Date.now(),eyebrow:str(b.eyebrow,90),title:str(b.title,180),body:str(b.body,4000),image:image(b.image),buttonLabel:str(b.buttonLabel,90),buttonUrl:safeUrl(b.buttonUrl),visible:b.visible!==false})).filter(b=>b.title||b.image);
return out;
}
