const REVIEW_CSS="\n:root{--bg:#f8fbf8;--ink:#162e1e;--muted:#5b7664;--line:#dceadf;--mint:#d6f5e0;--deep:#143b29}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);font:14px/1.75 Arial,sans-serif;color:var(--ink)}a{text-decoration:none;color:#216b46}button{font:inherit}\n.wrap{max-width:1120px;margin:auto;padding:22px}\nnav{background:#fff;border-bottom:1px solid var(--line)}nav .wrap{display:flex;align-items:center;justify-content:space-between;gap:15px}\n.brand{font-size:23px;font-weight:900;color:#153e2b}.brand b{color:#328961}\n.hero{padding:55px 0;background:radial-gradient(circle at 80% 20%,#d7f6e1,transparent 60%),#f2faf4}\n.bread{font-size:12px;font-weight:700;color:#558369}.split{display:grid;grid-template-columns:1fr 1.25fr;gap:36px;align-items:center}\n.figure{background:#fff;border:1px solid var(--line);border-radius:23px;min-height:370px;display:grid;place-items:center;position:relative;overflow:hidden}\n.figure img{width:100%;height:350px;object-fit:contain;padding:30px}.label{display:inline-block;border-radius:40px;background:#def5e5;padding:7px 12px;color:#246447;font-size:11px;font-weight:800}\nh1{font-size:clamp(32px,4vw,55px);line-height:1.13;margin:17px 0}h2{font-size:25px;margin:18px 0}p{color:var(--muted)}\n.actions{display:flex;flex-wrap:wrap;gap:10px;margin:26px 0}.btn{display:inline-block;background:#143b29;color:#fff;padding:12px 19px;border-radius:10px;font-size:13px;font-weight:800}.btn.alt{background:#e3f3e9;color:#18452e}\n.panel{background:#fff;border:1px solid var(--line);padding:30px;border-radius:20px;margin-top:22px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:13px 10px;text-align:left;border-bottom:1px solid #edf3ee}.table th{width:35%;color:#396d4f}\n.note{background:#ebf8ee;border:1px solid #d5eadc;border-radius:12px;padding:15px 20px;color:#436a50;font-size:12px}footer{padding:50px 0;color:#698370;font-size:12px}\n@media(max-width:720px){.split{grid-template-columns:1fr}.figure{min-height:270px}.figure img{height:270px;padding:15px}.panel{padding:18px}}\n";

const htmlEscape=(v)=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function reviewPage(p){
const specs=JSON.parse(p.specs||"{}");const image=p.image||"";
const visuals=image?'<img referrerpolicy="no-referrer" src="'+htmlEscape(image)+'" alt="Visuel : '+htmlEscape(p.name)+'">':'<svg width="290" height="240" viewBox="0 0 290 240" xmlns="http://www.w3.org/2000/svg"><rect width="290" height="240" rx="18" fill="#193f2d"/><circle cx="145" cy="100" r="66" stroke="#c8f3d7" stroke-width="5" fill="none"/><text x="145" y="113" font-size="22" text-anchor="middle" font-weight="bold" fill="#d8ffe6">PICO</text><text x="145" y="210" font-size="15" text-anchor="middle" fill="#e2f9ea">'+htmlEscape(p.category)+'</text></svg>';
const rows=Object.entries(specs).map(([k,v])=>'<tr><th>'+htmlEscape(k)+'</th><td>'+htmlEscape(v)+'</td></tr>').join('');
return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><meta name="description" content="'+htmlEscape(p.description)+'"><title>'+htmlEscape(p.name)+' – Fiche et analyse | PICO WEB</title><style>'+REVIEW_CSS+'</style></head><body><nav><div class="wrap"><a href="/" class="brand">✳ PICO <b>WEB</b></a><a href="/#reviews">← Toutes les analyses</a></div></nav><main><section class="hero"><div class="wrap"><div class="bread">PICO WEB / '+htmlEscape(p.category)+' / FICHE PRODUIT</div><div class="split"><div class="figure">'+visuals+'</div><div><span class="label">Analyse documentaire · Sans essai matériel</span><h1>'+htmlEscape(p.name)+'</h1><p>'+htmlEscape(p.description)+'</p><div class="actions"><a class="btn" href="/out/'+encodeURIComponent(p.id)+'" rel="sponsored nofollow noopener noreferrer" target="_blank">Consulter sur Amazon ↗</a><a class="btn alt" href="/#compare">Comparer avec un autre produit</a></div><p class="note">Le prix et la disponibilité sont à vérifier sur Amazon.fr. Le lien ne comporte pas actuellement de code d’affiliation PICO WEB. La photo est indicative : les variantes peuvent être différentes.</p></div></div></div></section><section class="wrap"><div class="panel"><h2>Caractéristiques indiquées</h2><table class="table">'+rows+'</table></div><div class="panel"><h2>Notre analyse</h2><p>'+htmlEscape(p.review||"Analyse complémentaire en préparation.")+'</p><p class="note">Cette fiche résume des caractéristiques constructeur et des compromis d’usage. Ce n’est pas un test effectué en personne ni une note issue d’acheteurs certifiés.</p></div></section></main><footer class="wrap">PICO WEB · Guides d’achat responsables · <a href="/">Accueil</a></footer></body></html>'
}

const STORE=[{id:"website",name:"Création de site vitrine",description:"Site responsive sur devis, selon besoins du client."},{id:"landing",name:"Landing page premium",description:"Page de présentation et conversion personnalisée."},{id:"template",name:"Template web personnalisé",description:"Maquette et fichiers à concevoir, selon cahier des charges."}];
const JSON_HEADERS={"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"};
const pageHeaders={"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer","X-Frame-Options":"DENY","Content-Security-Policy":"frame-ancestors 'none'; base-uri 'self'; form-action 'self'"};
const reply=(obj,status=200,headers={})=>new Response(JSON.stringify(obj),{status,headers:{...JSON_HEADERS,...headers}});
function fail(msg,status=400){return reply({error:msg},status)}
const secret=Bun.env.SESSION_SECRET||"";const password=Bun.env.ADMIN_PASSWORD||"";
const enc=new TextEncoder();
async function hmac(data){const key=await crypto.subtle.importKey("raw",enc.encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);const sig=await crypto.subtle.sign("HMAC",key,enc.encode(data));return Buffer.from(sig).toString("base64url")}
function same(a,b){const x=enc.encode(a||""),y=enc.encode(b||"");if(x.length!==y.length)return false;let diff=0;for(let i=0;i<x.length;i++)diff|=x[i]^y[i];return diff===0}
async function authed(req){if(!secret||!password)return false;const raw=(req.headers.get("cookie")||"").match(/(?:^|;\s*)pico_session=([^;]+)/)?.[1];if(!raw)return false;const [exp,nonce,sig]=raw.split(".");if(!exp||!nonce||!sig||Number(exp)<Date.now()||Number(exp)>Date.now()+8*3600_000)return false;return same(sig,await hmac(exp+"."+nonce))}
function originOk(req){const o=req.headers.get("origin");if(!o)return true;return o==="https://pico-web-live-production.up.railway.app"||o===Bun.env.SITE_URL}
async function body(req){const raw=await req.text();if(raw.length>40000)throw Error("Données trop volumineuses");return JSON.parse(raw||"{}")}
function validUrl(s){try{const u=new URL(s);return u.protocol==="https:"&&u.username===""&&u.password===""&&["amazon.fr","www.amazon.fr","amazon.com","www.amazon.com"].includes(u.hostname)}catch{return false}}
function validImg(s){if(!s)return true;if(s.startsWith("/media/")&&/^[a-f0-9-]{10,50}$/.test(s.slice(7)))return true;try{const u=new URL(s);return u.protocol==="https:"&&u.username===""&&u.password===""&&s.length<1400}catch{return false}}
function clean(v,max){return String(v??"").trim().slice(0,max)}
function slug(){return crypto.randomUUID().slice(0,12)}
function metric(k){db.query("INSERT INTO metrics(k,n) VALUES(?,1) ON CONFLICT(k) DO UPDATE SET n=n+1").run(k)}
const adminMetrics=()=>({pageviews:db.query("SELECT n FROM metrics WHERE k='pageviews'").get()?.n||0,clicks:db.query("SELECT n FROM metrics WHERE k='clicks'").get()?.n||0,byProduct:db.query("SELECT id,n FROM clicks ORDER BY n DESC").all()});
Bun.serve({port:Number(Bun.env.PORT||3000),async fetch(request){
const url=new URL(request.url),path=url.pathname,method=request.method;
try{
if(path==="/health")return new Response("ok",{headers:{"Content-Type":"text/plain"}});
if(path==="/"||path==="/index.html")return new Response(PAGE,{headers:pageHeaders});
if(path==="/admin"&&method==="GET")return new Response(ADMIN,{headers:pageHeaders});

if(path==="/api/site"&&method==="GET"){const isPreview=url.searchParams.get("preview")==="1"&&await authed(request);return reply({site:getCms(isPreview?"draft":"published"),preview:isPreview})}
if(path==="/cms-public.js"&&method==="GET")return new Response(CMS_PUBLIC_JS,{headers:{"Content-Type":"text/javascript; charset=utf-8","Cache-Control":"public,max-age=60","X-Content-Type-Options":"nosniff"}});
if(path.startsWith("/media/")&&method==="GET"){
const id=path.slice(7);if(!/^[a-f0-9-]{10,50}$/.test(id))return fail("Image introuvable",404);
const f=db.query("SELECT bytes,mime FROM cms_media WHERE id=?").get(id);
return f?new Response(f.bytes,{headers:{"Content-Type":f.mime,"Cache-Control":"public,max-age=604800","X-Content-Type-Options":"nosniff","Cross-Origin-Resource-Policy":"same-origin"}}):fail("Image introuvable",404)}

if(path.startsWith("/review/")&&method==="GET"){const id=decodeURIComponent(path.slice("/review/".length));const item=db.query("SELECT * FROM products WHERE id=? AND visible=1").get(id);return item?new Response(reviewPage(item),{headers:pageHeaders}):new Response("Produit introuvable",{status:404,headers:{"Content-Type":"text/plain"}})}
if(path==="/v2.js"&&method==="GET")return new Response(CLIENT_JS,{headers:{"Content-Type":"text/javascript; charset=utf-8","Cache-Control":"public,max-age=60","X-Content-Type-Options":"nosniff"}});
if(path==="/admin.js"&&method==="GET")return new Response(ADMIN_JS,{headers:{"Content-Type":"text/javascript; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});
if(path==="/cms-edit.js"&&method==="GET")return new Response(CMS_EDIT,{headers:{"Content-Type":"text/javascript; charset=utf-8","Cache-Control":"no-store"}});
if(path==="/robots.txt")return new Response("User-agent: *\nDisallow: /admin\nDisallow: /api/admin\nDisallow: /out/\nDisallow: /\n",{headers:{"Content-Type":"text/plain"}});
if(path==="/api/catalog"&&method==="GET")return reply({products:publicProducts(),articles:publicArticles(),store:STORE,affiliateActive:false,paymentsActive:false});
if(path==="/api/pageview"&&method==="POST"){if(!originOk(request))return fail("Origine refusée",403);metric("pageviews");return reply({ok:true})}
if(path.startsWith("/out/")&&method==="GET"){const id=decodeURIComponent(path.slice(5));const p=db.query("SELECT url FROM products WHERE id=? AND visible=1").get(id);if(!p||!validUrl(p.url))return fail("Lien indisponible",404);metric("clicks");db.query("INSERT INTO clicks(id,n) VALUES(?,1) ON CONFLICT(id) DO UPDATE SET n=n+1").run(id);return Response.redirect(p.url,302)}
if(path==="/api/checkout")return fail("Le paiement en ligne n'est pas encore activé. Aucun prélèvement possible.",503);
if(path==="/api/admin/login"&&method==="POST"){
if(!originOk(request))return fail("Origine refusée",403);
const prior=db.query("SELECT n,at FROM login_attempts WHERE k='global'").get();if(prior&&prior.n>=8&&Date.now()-prior.at<15*60_000)return fail("Trop de tentatives. Réessayez plus tard.",429);
const b=await body(request);if(!password||!secret||!same(clean(b.password,256),password)){db.query("INSERT INTO login_attempts(k,n,at) VALUES('global',1,?) ON CONFLICT(k) DO UPDATE SET n=CASE WHEN ?-at>900000 THEN 1 ELSE n+1 END, at=?").run(Date.now(),Date.now(),Date.now());return fail("Identifiants invalides",401)}
db.query("DELETE FROM login_attempts WHERE k='global'").run();const exp=Date.now()+8*3600_000,nonce=crypto.randomUUID();const t=exp+"."+nonce+"."+await hmac(exp+"."+nonce);return reply({ok:true},200,{"Set-Cookie":"pico_session="+t+"; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=28800"})
}
if(path==="/api/admin/logout"&&method==="POST")return reply({ok:true},200,{"Set-Cookie":"pico_session=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0"});
if(path.startsWith("/api/admin/")){
if(!(await authed(request)))return fail("Accès réservé à l'administrateur",401);
if(method!=="GET"&&!originOk(request))return fail("Origine refusée",403);
if(path==="/api/admin/data"&&method==="GET")return reply({products:allProducts(),articles:allArticles(),analytics:adminMetrics()});

if(path==="/api/admin/cms"&&method==="GET")return reply({draft:getCms("draft"),published:getCms("published"),history:db.query("SELECT id,created FROM cms_history ORDER BY id DESC LIMIT 12").all()});
if(path==="/api/admin/cms"&&method==="POST"){const b=await body(request),d=cmsClean(b.site);setCms("draft",d);return reply({ok:true,site:d})}
if(path==="/api/admin/cms/publish"&&method==="POST"){const b=await body(request),d=cmsClean(b.site);db.query("INSERT INTO cms_history(json,created) VALUES(?,?)").run(JSON.stringify(getCms("published")),Date.now());setCms("draft",d);setCms("published",d);return reply({ok:true})}
if(path==="/api/admin/cms/restore"&&method==="POST"){const b=await body(request);if(!Number.isSafeInteger(b.id))return fail("Version incorrecte");const h=db.query("SELECT json FROM cms_history WHERE id=?").get(b.id);if(!h)return fail("Version introuvable",404);const d=cmsClean(JSON.parse(h.json));setCms("draft",d);return reply({ok:true,site:d})}
if(path==="/api/admin/media"&&method==="GET")return reply({media:db.query("SELECT id,name,mime,size,created FROM cms_media ORDER BY created DESC LIMIT 160").all()});
if(path==="/api/admin/media"&&method==="POST"){
const form=await request.formData(),f=form.get("file");
if(!f||typeof f.arrayBuffer!=="function")return fail("Choisissez une image");
if(f.size>3*1024*1024||f.size<50)return fail("Image trop grande (max 3 Mo) ou vide",413);
const data=new Uint8Array(await f.arrayBuffer());let mime="";
if(data.length>8&&data[0]===255&&data[1]===216&&data[2]===255)mime="image/jpeg";
if(data.length>8&&data[0]===137&&data[1]===80&&data[2]===78&&data[3]===71)mime="image/png";
if(data.length>12&&String.fromCharCode(...data.slice(0,4))==="RIFF"&&String.fromCharCode(...data.slice(8,12))==="WEBP")mime="image/webp";
if(!mime)return fail("Format autorisé : JPG, PNG, WEBP");
const id=crypto.randomUUID(),name=clean(f.name,150);
db.query("INSERT INTO cms_media(id,name,mime,bytes,size,created) VALUES(?,?,?,?,?,?)").run(id,name,mime,data,data.length,Date.now());
return reply({ok:true,id,url:"/media/"+id,name},201)}
if(path.startsWith("/api/admin/media/")&&method==="DELETE"){db.query("DELETE FROM cms_media WHERE id=?").run(path.slice("/api/admin/media/".length));return reply({ok:true})}

if(path==="/api/admin/product"&&method==="POST"){
const b=await body(request);const id=clean(b.id,80)||slug(),name=clean(b.name,100),category=clean(b.category,30),u=clean(b.url,1200),im=clean(b.image,1400),desc=clean(b.description,700),rev=clean(b.review,1000);if(!name||!["Souris","Casque","Clavier","Autre"].includes(category)||!validUrl(u)||!validImg(im))return fail("Nom, catégorie, URL Amazon.fr HTTPS ou image invalide.");
let specs={};if(b.specs&&typeof b.specs==="object"&&!Array.isArray(b.specs)){for(const [k,v] of Object.entries(b.specs).slice(0,20))specs[clean(k,50)]=clean(v,130)}
db.query("INSERT INTO products(id,name,category,url,image,description,specs,review,visible) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,url=excluded.url,image=excluded.image,description=excluded.description,specs=excluded.specs,review=excluded.review,visible=excluded.visible").run(id,name,category,u,im,desc,JSON.stringify(specs),rev,b.visible?1:0);return reply({ok:true,id})
}
if(path.startsWith("/api/admin/product/")&&method==="DELETE"){db.query("DELETE FROM products WHERE id=?").run(path.slice(19));return reply({ok:true})}
if(path==="/api/admin/article"&&method==="POST"){const b=await body(request),id=clean(b.id,80)||slug(),title=clean(b.title,140),summary=clean(b.summary,400),content=clean(b.body,14000);if(!title||content.length<20)return fail("Titre et article (20 caractères minimum) requis");db.query("INSERT INTO articles(id,title,summary,body,published) VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,summary=excluded.summary,body=excluded.body,published=excluded.published").run(id,title,summary,content,b.published?1:0);return reply({ok:true,id})}
if(path.startsWith("/api/admin/article/")&&method==="DELETE"){db.query("DELETE FROM articles WHERE id=?").run(path.slice(19));return reply({ok:true})}
return fail("Route inconnue",404)
}
return new Response("Page introuvable",{status:404,headers:{"Content-Type":"text/plain"}})
}catch(e){return fail("Requête impossible",400)}
}});
